<script lang="ts">
  import { refreshUsageHistory, usageState } from './usageStore.svelte.ts';
  import { usageProviderLabel } from './usageCurrent.ts';

  const numberFormat = new Intl.NumberFormat('en-US');
  function totalTokens(): number {
    const summary = usageState.summary;
    return summary ? summary.inputTokens + summary.outputTokens + summary.cacheReadTokens + summary.cacheWriteTokens + summary.reasoningTokens : 0;
  }
  function visibleTokens(input: number): string {
    if (input >= 1_000_000_000) return `${(input / 1_000_000_000).toFixed(1)}B`;
    if (input >= 1_000_000) return `${(input / 1_000_000).toFixed(1)}M`;
    if (input >= 1_000) return `${(input / 1_000).toFixed(1)}K`;
    return numberFormat.format(input);
  }
  function costLabel(value: number | null): string { return value == null ? 'Unavailable' : `$${(value / 1_000_000).toFixed(2)}`; }
  function cacheShare(): number { const summary = usageState.summary; if (!summary) return 0; const total = totalTokens(); return total === 0 ? 0 : Math.round(((summary.cacheReadTokens + summary.cacheWriteTokens) / total) * 100); }
  function intensity(row: { inputTokens: number; outputTokens: number }): number { const max = Math.max(...usageState.daily.map((item) => item.inputTokens + item.outputTokens), 1); return Math.min(4, Math.ceil(((row.inputTokens + row.outputTokens) / max) * 4)); }
  function formatDay(day: string): string { const parsed = new Date(`${day}T00:00:00Z`); return Number.isNaN(parsed.getTime()) ? day : parsed.toLocaleDateString([], { month: 'short', day: 'numeric', timeZone: 'UTC' }); }
  let providerCards = $derived(usageState.providerSummary);
</script>

<section class="workspace" data-testid="usage-workspace" aria-label="Stats and Usage">
  <header class="workspace-header"><div><p class="eyebrow">Stats &amp; Usage</p><h2>Provider activity</h2><p class="muted">Local transcripts are indexed incrementally; aggregates stay in SQLite.</p></div><button type="button" onclick={() => void refreshUsageHistory()} disabled={usageState.loading}>{usageState.loading ? 'Indexing…' : 'Refresh'}</button></header>
  {#if usageState.summary}
    <div class="top-tiles"><div><strong>{numberFormat.format(usageState.summary.sessionCount)}</strong><span>Agents spawned</span></div><div><strong>{usageState.summary.activeDays ? `${usageState.summary.activeDays}d` : '—'}</strong><span>Active days</span></div><div><strong>—</strong><span>PRs created · not indexed</span></div></div>
    <p class="tracking">Tracking local usage · {usageState.summary.eventCount.toLocaleString('en-US')} explicit events</p>
    <section class="analytics-card"><div class="section-heading"><div><h3>Usage Overview</h3><p class="muted">Updated from the local index</p></div><button type="button" aria-label="Refresh analytics" onclick={() => void refreshUsageHistory()}>↻</button></div><div class="metric-grid"><div><strong>{visibleTokens(totalTokens())}</strong><span>Total tokens</span></div><div><strong>{costLabel(usageState.summary.estimatedCostMicros)}</strong><span>Est. cost</span></div><div><strong>{usageState.summary.activeDays}</strong><span>Active days</span></div><div><strong>{cacheShare()}%</strong><span>Cache share</span></div></div><div class="charts"><section class="chart"><div class="chart-heading"><div><h3>Daily intensity</h3><p class="muted">Input and output token activity by indexed day.</p></div><span class="badge">{usageState.daily.length} days</span></div><div class="heatmap">{#each usageState.daily.slice().reverse() as row (`${row.day}:${row.provider}:${row.model}`)}<span class={`level-${intensity(row)}`} title={`${formatDay(row.day)} · ${visibleTokens(row.inputTokens + row.outputTokens)}`}></span>{/each}</div><div class="legend"><span>{usageState.daily.length ? formatDay(usageState.daily[usageState.daily.length - 1].day) : 'No data'}</span><span>Less</span><i class="level-1"></i><i class="level-2"></i><i class="level-3"></i><i class="level-4"></i><span>More</span><span>{usageState.daily[0] ? formatDay(usageState.daily[0].day) : ''}</span></div></section><section class="chart"><div class="chart-heading"><div><h3>Token mix</h3><p class="muted">Input, output, cache, and reasoning.</p></div><span class="badge">{visibleTokens(totalTokens())}</span></div><div class="mix-bar"><i class="input" style={`width:${totalTokens() ? (usageState.summary.inputTokens / totalTokens()) * 100 : 0}%`}></i><i class="output" style={`width:${totalTokens() ? (usageState.summary.outputTokens / totalTokens()) * 100 : 0}%`}></i><i class="cache" style={`width:${totalTokens() ? ((usageState.summary.cacheReadTokens + usageState.summary.cacheWriteTokens) / totalTokens()) * 100 : 0}%`}></i><i class="reasoning" style={`width:${totalTokens() ? (usageState.summary.reasoningTokens / totalTokens()) * 100 : 0}%`}></i></div><div class="mix-legend"><span><i class="dot input"></i>Input {visibleTokens(usageState.summary.inputTokens)}</span><span><i class="dot output"></i>Output {visibleTokens(usageState.summary.outputTokens)}</span><span><i class="dot cache"></i>Cache {visibleTokens(usageState.summary.cacheReadTokens + usageState.summary.cacheWriteTokens)}</span></div></section></div></section>
    <section class="providers"><div class="section-heading"><div><h3>Providers</h3><p class="muted">{providerCards.length} indexed provider{providerCards.length === 1 ? '' : 's'}</p></div><span class="badge">{usageState.summary.eventCount} events</span></div><div class="provider-grid">{#each providerCards as card (card.provider)}<article><div class="provider-heading"><h3>{usageProviderLabel(card.provider)}</h3><span>Indexed</span></div><p class="muted">{card.models.join(' · ')}</p><div class="provider-stats"><span>{visibleTokens(card.inputTokens + card.outputTokens)}<small>tokens</small></span><span>{card.sessionCount}<small>sessions</small></span><span>{card.eventCount}<small>events</small></span></div><div class="provider-bar"><i style={`width:${Math.min(100, ((card.inputTokens + card.outputTokens) / Math.max(...providerCards.map((item) => item.inputTokens + item.outputTokens), 1)) * 100)}%`}></i></div></article>{/each}{#if providerCards.length === 0}<p class="muted">No provider activity has been indexed yet.</p>{/if}</div></section>
  {:else}<p class="empty">{usageState.error ?? 'Refresh to index local usage history.'}</p>{/if}
</section>

