  .tracking { font-size: 0.78rem; } .analytics-card, .providers { display: grid; gap: 1rem; padding: 1rem; border: 1px solid var(--color-border); border-radius: 0.65rem; } .section-heading, .chart-heading, .provider-heading { display: flex; justify-content: space-between; align-items: start; gap: 0.7rem; } .badge { border: 1px solid var(--color-border); border-radius: 9rem; padding: 0.2rem 0.55rem; color: var(--color-text-2); font-size: 0.73rem; white-space: nowrap; }
  .charts { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(15rem, 0.9fr); gap: 0.8rem; } .chart { display: grid; gap: 0.8rem; padding: 0.8rem; border: 1px solid var(--color-border); border-radius: 0.55rem; } .heatmap { display: grid; grid-template-columns: repeat(14, minmax(0, 1fr)); gap: 0.25rem; min-height: 4.2rem; align-content: center; } .heatmap span, .legend i { width: 100%; aspect-ratio: 1; border: 1px solid var(--color-border); border-radius: 0.2rem; background: var(--color-elevated); } .level-1 { background: color-mix(in srgb, var(--color-accent) 20%, var(--color-elevated)) !important; } .level-2 { background: color-mix(in srgb, var(--color-accent) 40%, var(--color-elevated)) !important; } .level-3 { background: color-mix(in srgb, var(--color-accent) 65%, var(--color-elevated)) !important; } .level-4 { background: var(--color-accent) !important; } .legend { display: flex; align-items: center; gap: 0.25rem; color: var(--color-text-2); font-size: 0.7rem; } .legend span:first-child { margin-right: auto; } .legend span:nth-last-child(1) { margin-left: auto; } .legend i { width: 0.7rem; flex: 0 0 auto; }
  .mix-bar, .provider-bar { display: flex; height: 0.55rem; overflow: hidden; border-radius: 9rem; background: var(--color-border); } .mix-bar i, .provider-bar i { display: block; min-width: 0; } .input { background: var(--color-accent); } .output { background: var(--color-good); } .cache { background: var(--color-attention); } .reasoning { background: var(--color-live); } .mix-legend { display: grid; gap: 0.35rem; color: var(--color-text-2); font-size: 0.73rem; } .mix-legend span { display: flex; align-items: center; gap: 0.35rem; } .dot { width: 0.55rem; height: 0.55rem; border-radius: 50%; }
  .provider-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 0.7rem; } .provider-grid article { display: grid; gap: 0.6rem; padding: 0.85rem; border: 1px solid var(--color-border); border-radius: 0.55rem; } .provider-heading span { color: var(--color-good); font-size: 0.75rem; } .provider-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.5rem; } .provider-stats span { display: grid; gap: 0.15rem; font-size: 1rem; } .provider-stats small { font-size: 0.7rem; } .provider-bar i { background: var(--color-accent); }
  @media (max-width: 48rem) { .top-tiles, .metric-grid, .charts { grid-template-columns: 1fr 1fr; } .charts .chart:first-child { grid-column: 1 / -1; } } @media (max-width: 32rem) { .top-tiles, .metric-grid, .charts { grid-template-columns: 1fr; } }
